function escPedidoCliente(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}if(!obterTokenCliente())location.href='login.html';(async()=>{const n=new URLSearchParams(location.search).get('numero');if(!n)return;try{const p=await apiFetch('/pedidos/meus/'+encodeURIComponent(n));document.getElementById('pd-titulo').textContent='Encomenda #'+p.numeroPedido;document.getElementById('pd-migalha').textContent='Pedido #'+p.numeroPedido;document.getElementById('pd-estado').textContent='Estado: '+estadoPT(p.estado)+(p.pagamento&&p.pagamento.estado==='pendente'?' · Pagamento pendente de confirmação':'');document.getElementById('pd-itens').innerHTML=(p.itens||[]).map(i=>`<div class="linha-resumo"><span>${escPedidoCliente(i.nome_produto||i.nome||'Produto')} ×${i.quantidade||1}</span><span>${Number(i.subtotal_eur||(Number(i.preco_unitario_eur||0)*Number(i.quantidade||1))||0).toLocaleString('pt-PT',{style:'currency',currency:'EUR'})}</span></div>`).join('');document.getElementById('pd-portes').textContent=p.totalEUR? 'Incluído no total':'—';document.getElementById('pd-total').textContent=Number(p.totalEUR||0).toLocaleString('pt-PT',{style:'currency',currency:'EUR'});}catch(e){document.getElementById('pd-estado').textContent=e.message}})();
